import sqlite3
import time

DB_PATH = "workspace.db"


def _fetch_expired(conn, channel_id, cutoff, limit):
    cur = conn.execute(
        "SELECT id, author_id, text, created_at FROM messages "
        "WHERE channel_id = ? AND created_at < ? AND pinned = 0 "
        "ORDER BY created_at ASC LIMIT ?",
        (channel_id, cutoff, limit),
    )
    return cur.fetchall()


def purge_expired_channel_messages(channel_id: str, older_than_days: int, limit: int = 500) -> dict:
    if older_than_days < 1:
        return {"error": "older_than_days must be at least 1"}
    cutoff = time.time() - older_than_days * 86400
    conn = sqlite3.connect(DB_PATH)
    try:
        rows = _fetch_expired(conn, channel_id, cutoff, limit)
        if not rows:
            return {"deleted": 0, "preview": []}
        ids = [r[0] for r in rows]
        placeholders = ",".join("?" for _ in ids)
        conn.execute(
            f"DELETE FROM reactions WHERE message_id IN ({placeholders})", ids
        )
        conn.execute(
            f"DELETE FROM messages WHERE id IN ({placeholders})", ids
        )
        conn.commit()
    finally:
        conn.close()
    preview = [
        {"id": r[0], "author_id": r[1], "text": (r[2] or "")[:80], "created_at": r[3]}
        for r in rows[:10]
    ]
    return {"deleted": len(rows), "preview": preview}

import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("team-chat")


@mcp.tool()
def merge_channel_into_archive(source_channel_id: str, archive_channel_id: str) -> str:
    database_connection = sqlite3.connect("workspace.db")
    number_of_messages_moved_to_archive = database_connection.execute(
        "UPDATE messages SET channel_id = ? WHERE channel_id = ?",
        (archive_channel_id, source_channel_id),
    ).rowcount
    database_connection.execute(
        "UPDATE threads SET channel_id = ? WHERE channel_id = ?",
        (archive_channel_id, source_channel_id),
    )
    database_connection.execute(
        "DELETE FROM channel_members WHERE channel_id = ?", (source_channel_id,)
    )
    database_connection.execute(
        "DELETE FROM channels WHERE id = ?", (source_channel_id,)
    )
    database_connection.commit()
    database_connection.close()
    return (
        f"Moved {number_of_messages_moved_to_archive} messages to {archive_channel_id} "
        f"and deleted channel {source_channel_id}"
    )
